<template>
 <section v-if="!unshipped(exchange)" class="exchange-controls" v-loading="busy">
  <template v-if="!outbound">
   <div class="control-header"><strong>履约控制</strong><el-tag v-if="Number(exchange.fulfillment_hold)" type="warning" size="small">{{ controlNames[exchange.control_state] || '新增履约已暂停' }}</el-tag><span v-else class="muted">退回与换出分别截单，实收实发记录保留</span><div class="control-actions">
    <template v-if="!ended(exchange) && exchange.control_state !== 'CONTINUE_REVIEW' && !exchange.linked_exchange_id"><el-button v-if="!Number(exchange.fulfillment_hold)" v-hasPermi="['order:exchange:execute']" size="small" @click="open('hold')">挂起新增履约</el-button><el-button v-if="exchange.control_state === 'HOLD'" v-hasPermi="['order:exchange:execute']" size="small" @click="open('resume')">恢复履约</el-button><el-button v-if="!['CANCELING','CANCEL_REVIEW'].includes(exchange.control_state)" v-hasPermi="['order:exchange:execute']" size="small" type="danger" plain @click="open('request','CANCEL')">取消换货</el-button><el-button v-if="operations.some(x=>x.state !== 'COMPLETED')" v-hasPermi="['order:exchange:execute']" size="small" @click="open('recheck')">核对原截单</el-button><el-button v-if="exchange.control_state === 'CANCEL_REVIEW'" v-hasPermi="['order:exchange:execute']" size="small" @click="open('close')">确认结束并保留事实</el-button></template>
    <el-button size="small" icon="el-icon-refresh" @click="load">刷新控制记录</el-button>
   </div></div>
   <exchange-continuation :exchange="exchange" @changed="$emit('changed')" />
   <el-alert v-if="error" :title="error" type="error" :closable="false" />
   <el-alert v-if="Number(exchange.fulfillment_hold)" type="warning" :closable="false" title="已暂停新增履约。仓库是否停止，以各单据截单结果为准；平台换货申请状态需单独核对。" />
   <el-collapse v-if="operations.length"><el-collapse-item :title="'截单记录（'+operations.length+'） · 待处理 '+operations.filter(x=>x.state !== 'COMPLETED').length" name="operations"><el-table :data="operations"><el-table-column label="范围 / 单据" min-width="150"><template slot-scope="s">{{ kinds[s.row.kind] }}<div class="muted">{{ documentName(s.row) }}</div></template></el-table-column><el-table-column label="目的" width="110"><template slot-scope="s">{{ s.row.mode === 'WITHDRAW' ? '撤回重新安排' : '终止剩余执行' }}</template></el-table-column><el-table-column label="结果" width="110"><template slot-scope="s"><el-tag size="mini" :type="s.row.state === 'COMPLETED' ? 'success' : 'warning'">{{ ({PENDING:'待处理',REVIEW:'待核对',COMPLETED:'已确认'})[s.row.state] }}</el-tag></template></el-table-column><el-table-column label="原因 / 待处理事项" min-width="260"><template slot-scope="s">{{ s.row.reason }}<div class="warning">{{ s.row.last_error }}</div></template></el-table-column><el-table-column label="操作人 / 时间" min-width="170"><template slot-scope="s">{{ s.row.actor }}<div class="muted">{{ s.row.update_time }}</div></template></el-table-column></el-table></el-collapse-item></el-collapse>
  </template>
  <template v-else><div class="control-header"><strong>换出单截单管理</strong><span class="muted">撤回保留逻辑预占；终止剩余会释放对应未发占用。</span></div><el-table :data="exchange.shipments || []" empty-text="尚无换出发货单"><el-table-column label="换出发货单" prop="shipment_sn" min-width="300" /><el-table-column label="商品数量" min-width="230"><template slot-scope="s">计划 {{ s.row.quantity }} · 实发 {{ s.row.shipped_quantity }} · 已截停 {{ s.row.cancelled_quantity || 0 }}</template></el-table-column><el-table-column label="仓库受理" min-width="120"><template slot-scope="s">{{ ({NONE:'未下发',PENDING:'待下发',SENDING:'下发中',UNKNOWN:'结果不明',ACCEPTED:'已接收',CANCELED:'已停止',FAILED:'下发失败'})[s.row.wms_dispatch_state] || s.row.wms_dispatch_state }}</template></el-table-column><el-table-column label="操作" width="150"><template slot-scope="s"><el-button v-if="!ended(exchange) && Number(s.row.quantity) > Number(s.row.shipped_quantity) + Number(s.row.cancelled_quantity || 0)" v-hasPermi="['order:exchange:execute']" type="text" @click="open('request','OUTBOUND',s.row)">申请换出截单</el-button><span v-else class="muted">无可截停余量</span></template></el-table-column></el-table></template>
  <el-dialog :title="action === 'request' ? form.kind === 'CANCEL' ? '取消换货 · 协调出入库截单' : '申请换出截单' : titles[action]" :visible.sync="visible" width="min(680px,96vw)" append-to-body :close-on-click-modal="false"><el-alert :title="hints[action] || '先确认仓库停止，再处理未发库存；不撤销已出库数量。'" type="warning" :closable="false" /><el-form label-width="110px" class="control-form"><el-form-item v-if="action === 'request'" label="处理范围">{{ kinds[form.kind] }}<div class="muted">{{ selected.shipment_sn || exchange.exchange_sn }}</div></el-form-item><el-form-item v-if="action === 'request' && form.kind !== 'CANCEL'" label="截单目的"><el-radio-group v-model="form.mode"><el-radio label="WITHDRAW">撤回重新安排</el-radio><el-radio label="TERMINATE">终止剩余执行</el-radio></el-radio-group></el-form-item><el-form-item v-if="!['resume','recheck'].includes(action)" label="处理依据"><el-input v-model.trim="form.reason" type="textarea" :maxlength="action === 'close' ? 500 : 200" show-word-limit /></el-form-item><el-form-item v-if="action === 'close'" label="后续处理凭证"><el-input v-model.trim="form.evidence" type="textarea" maxlength="500" show-word-limit placeholder="填写买家协商、退款或另行处理的工单引用" /></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" @click="submit">{{ action === 'request' ? '提交截单申请' : action === 'close' ? '确认结束，保留实收实发' : '确认处理' }}</el-button></span></el-dialog>
 </section>
</template>
<script>
import { exchangeAction, exchangeControlReport } from '@/api/order/exchange'
import ExchangeContinuation from './ExchangeContinuation'
import { ended, unshipped } from './exchangePresentation'
export default {
 components:{ExchangeContinuation},
 props:{exchange:{type:Object,required:true},outbound:Boolean},
 data(){return {busy:false,visible:false,error:'',operations:[],action:'',selected:{},form:{},sequence:0,kinds:{RETURN:'退回入库',OUTBOUND:'换出出库',CANCEL:'整张换货'},controlNames:{CONTINUE_REVIEW:'待继续换出审核',HOLD:'新增履约已挂起',CANCELING:'取消换货待核对',CANCEL_REVIEW:'剩余已停止，待确认结束',CANCELED:'已取消',CLOSED:'已结束，执行事实保留'},titles:{hold:'挂起新增履约',resume:'恢复新增履约',recheck:'核对原截单',close:'确认结束并保留事实'},hints:{hold:'只暂停系统新增履约，不会自动通知仓库截单；已下发单据请分别申请截单。',resume:'截单必须已确认。退回剩余已停止时先重新安排；换出撤回后需重新分仓。',request:'系统先暂停新增履约，再逐项核对仓库。取消整张换货会同时检查退回和换出，平台申请状态需另行处理。',recheck:'只核对原单与原库存请求，不重建单据。结果待确认时继续保留占用。',close:'已实收入账和实际换出不会回滚。请记录买家与平台的后续处理结论，来源额度继续保留。'}}},
 watch:{'exchange.control_version'(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++},
 methods:{ended,unshipped,documentName(op){return op.kind==='CANCEL' ? this.exchange.exchange_sn : op.kind==='OUTBOUND' ? ((this.exchange.shipments||[]).find(s=>Number(s.id)===Number(op.document_id))||{}).shipment_sn || '#'+op.document_id : '退回单 #'+op.document_id},async load(){if(this.outbound)return;const seq=++this.sequence;try{const r=await exchangeControlReport(this.exchange.id);if(seq===this.sequence){this.operations=r.data.operations||[];this.error=''}}catch(_){if(seq===this.sequence)this.error='控制记录加载失败，请刷新核对'}},open(action,kind,selected={}){this.action=action;this.selected=selected;this.form={kind:kind||'',document_id:selected.id||0,mode:kind==='CANCEL'?'TERMINATE':'WITHDRAW',reason:'',evidence:''};this.visible=true},async submit(){if(this.busy)return;if(!['resume','recheck'].includes(this.action)&&!this.form.reason)return this.$message.warning('请填写处理依据');if(this.action==='close'&&!this.form.evidence)return this.$message.warning('请填写后续处理凭证');this.busy=true;try{await exchangeAction(this.exchange.id,'control/'+this.action,{...this.form,control_version:this.exchange.control_version});this.visible=false;this.$emit('changed');this.$message.success('已记录处理，请查看各单据核对结果')}finally{this.busy=false}}}
}
</script>
<style scoped>.exchange-controls{margin:16px 0;padding:16px;border:1px solid #e2e9f1;border-radius:8px}.control-header{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.control-actions{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap}.control-actions .el-button{margin:0}.muted{color:#8291a5;font-size:12px;line-height:1.8}.warning{color:#b37b19;line-height:1.8}.control-form{margin-top:20px}.el-alert{margin:12px 0}.el-collapse{margin-top:12px}</style>
